import{_ as a,c as e,o as r,a1 as l}from"./chunks/framework.Be0jKih-.js";const g=JSON.parse('{"title":"Webbens samhällspåverkan","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/social-impact.md","filePath":"web1/3-web/social-impact.md"}'),n={name:"web1/3-web/social-impact.md"},s=l('<h1 id="webbens-samhallspaverkan" tabindex="-1">Webbens samhällspåverkan <a class="header-anchor" href="#webbens-samhallspaverkan" aria-label="Permalink to &quot;Webbens samhällspåverkan&quot;">​</a></h1><p>Webben har förändrat världen på många sätt sedan den skapades. Idag använder vi den för att kommunicera, lära oss nya saker, handla, och till och med för att jobba. Men webbens påverkan går mycket djupare än så. Den har förändrat hur vi lever våra liv, hur företag fungerar och hur samhället utvecklas.</p><p>Här visas flera område och exempel med förklaringar om hur webben har påverkat olika delar av samhället och varför den är en så viktig del av vår vardag.</p><h2 id="samhallsomrade" tabindex="-1">Samhällsområde <a class="header-anchor" href="#samhallsomrade" aria-label="Permalink to &quot;Samhällsområde&quot;">​</a></h2><ul><li><p><span class="a">Kommunikation</span></p><ul><li><span class="f">Förr</span>: Man skickade brev eller ringde telefonsamtal.</li><li><span class="f">Nu</span>: Vi kan kommunicera i realtid genom e-post, sociala medier och videosamtal. Detta har gjort världen mer sammanlänkad.</li></ul></li><li><p><span class="a">Utbildning</span></p><ul><li>Tack vare webben kan människor lära sig nästan vad som helst online. Plattformar som <span class="f">YouTube</span> erbjuder gratis utbildningsresurser.</li></ul></li><li><p><span class="a">Ekonomi</span></p><ul><li><span class="f">E-handel</span> har gjort det enkelt att köpa och sälja produkter globalt. Företag kan nå kunder över hela världen utan att behöva fysiska butiker.</li></ul></li><li><p><span class="a">Kultur och underhållning</span></p><ul><li>Webben har förändrat hur vi konsumerar musik, film och böcker. Streamingplattformar som <span class="f">Spotify</span> och <span class="f">Netflix</span> har blivit populära.</li></ul></li><li><p><span class="a">Demokrati och yttrandefrihet</span></p><ul><li>Webben har gett människor en plattform att uttrycka sina åsikter. Sociala medier har spelat en viktig roll i politiska rörelser och protester.</li></ul></li><li><p><span class="a">Utmaningar</span></p><ul><li>Trots många fördelar finns det också problem. Exempelvis spridning av <span class="f">desinformation</span>, <span class="f">näthat</span> och <span class="f">integritetsfrågor</span>.</li></ul></li></ul><br><h2 id="nagra-exempel-pa-webbens-samhallspaverkan" tabindex="-1">Några exempel på webbens samhällspåverkan <a class="header-anchor" href="#nagra-exempel-pa-webbens-samhallspaverkan" aria-label="Permalink to &quot;Några exempel på webbens samhällspåverkan&quot;">​</a></h2><ol><li><p><span class="a">Google – Att hitta information snabbt</span></p><ul><li>Förklaring: Google är en sökmotor som gör det möjligt att hitta information på några sekunder. Förr var man tvungen att leta i böcker eller arkiv för att hitta fakta, men nu kan man få svar direkt.</li><li>Påverkan: Google har revolutionerat hur vi söker och använder kunskap. Det har gjort forskning och problemlösning enklare för både studenter och yrkesverksamma.</li></ul></li><li><p><span class="a">Spotify – Musikstreaming</span></p><ul><li>Förklaring: Spotify har förändrat hur vi lyssnar på musik genom att erbjuda miljontals låtar direkt i mobilen eller datorn.</li><li>Påverkan: Förr köpte man CD-skivor eller laddade ner musik, men nu kan man streama allt från klassisk musik till de senaste hitsen. Detta har också gett nya artister en plattform att nå ut till en global publik.</li></ul></li><li><p><span class="a">Netflix och filmindustrin</span></p><ul><li>Förklaring: Netflix har förändrat hur vi tittar på film och serier genom att erbjuda streamingtjänster.</li><li>Påverkan: Filmindustrin har anpassat sig till denna nya modell, och det har gett upphov till fler originalproduktioner som når en global publik.</li></ul></li><li><p><span class="a">E-handel och småföretag – Etsy</span></p><ul><li>Förklaring: Etsy är en plattform där småföretag och hantverkare kan sälja sina produkter globalt.</li><li>Påverkan: Det har gjort det möjligt för kreativa entreprenörer att nå en bredare marknad utan att behöva ha en fysisk butik.</li></ul></li><li><p><span class="a">Influencers och sociala medier som karriär</span></p><ul><li>Förklaring: Sociala medier har skapat nya yrken, som influencers, som bygger sina karriärer genom att skapa innehåll på plattformar som Instagram, TikTok och YouTube.</li><li>Påverkan: Detta har öppnat nya möjligheter för entreprenörskap, men det har också påverkat konsumtionsmönster och ungas syn på framgång.</li></ul></li><li><p><span class="a">Onlinehälsa – Digitala vårdtjänster</span></p><ul><li>Förklaring: Tjänster som Kry och Min Doktor erbjuder digitala läkarbesök via webben eller en app.</li><li>Påverkan: Patienter kan få hjälp snabbt utan att behöva besöka en fysisk vårdcentral. Detta har särskilt hjälpt människor i glesbygden eller under tider med hög belastning i vården.</li></ul></li><li><p><span class="a">Teams och digitala möten</span></p><ul><li>Förklaring: Verktyg som Microsoft Teams, Google Meet och Zoom gör det möjligt att ha möten online, oavsett var man befinner sig.</li><li>Påverkan: Under pandemin blev dessa verktyg avgörande för distansarbete och distansutbildning. De har också minskat behovet av resor, vilket sparar tid och är bättre för miljön.</li></ul></li><li><p><span class="a">Crowdfunding – Kickstarter och GoFundMe</span></p><ul><li>Förklaring: Plattformar som Kickstarter och GoFundMe gör det möjligt för privatpersoner och företag att samla in pengar till projekt eller välgörenhet online.</li><li>Påverkan: Många innovativa idéer och företag har blivit verklighet tack vare stöd från människor över hela världen. Det har också gjort det lättare att hjälpa personer i nöd.</li></ul></li><li><p><span class="a">Wikipedia och öppna databaser</span></p><ul><li>Förklaring: Wikipedia är en av världens största informationskällor som bygger på bidrag från frivilliga.</li><li>Påverkan: Det har gjort kunskap tillgänglig för alla, oavsett var de befinner sig, och visat kraften i samarbeten på webben.</li></ul></li><li><p><span class="a">Digital aktivism – #MeToo och Black Lives Matter</span></p><ul><li>Förklaring: Sociala medier har blivit en plattform för sociala rörelser, som <strong>#MeToo</strong> och <strong>Black Lives Matter</strong>, där människor kan dela sina berättelser och kräva förändring.</li><li>Påverkan: Dessa rörelser har lett till ökad medvetenhet om samhällsproblem och pressat makthavare att agera.</li></ul></li></ol>',8),t=[s];function i(o,p,m,k,h,d){return r(),e("div",null,t)}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
